import { test, expect } from '@playwright/test';

test.describe('Field Validation Error Messages', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/form');
    // Wait for form to be fully loaded
    await page.waitForLoadState('networkidle');
  });

  test('should display specific validation error for empty email field', async ({ page }) => {
    // Fill in other fields but leave email empty
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Password').fill('SecurePass123!');

    // Submit the form
    await page.getByRole('button', { name: 'Submit' }).click();

    // Verify specific error message for email field
    const emailError = page.getByText('Email is required');
    await expect(emailError).toBeVisible();

    // Verify error is associated with email field
    const emailField = page.getByLabel('Email');
    const emailContainer = emailField.locator('..');
    await expect(emailContainer).toContainText('Email is required');
  });

  test('should display specific validation error for invalid email format', async ({ page }) => {
    // Fill in form with invalid email
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Email').fill('invalid-email-format');
    await page.getByLabel('Password').fill('SecurePass123!');

    // Submit the form
    await page.getByRole('button', { name: 'Submit' }).click();

    // Verify specific error message for invalid email format
    const emailFormatError = page.getByText('Please enter a valid email address');
    await expect(emailFormatError).toBeVisible();
  });

  test('should display specific validation error for weak password', async ({ page }) => {
    // Fill in form with weak password
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Email').fill('john@example.com');
    await page.getByLabel('Password').fill('weak');

    // Submit the form
    await page.getByRole('button', { name: 'Submit' }).click();

    // Verify specific error message for weak password
    const passwordError = page.getByText('Password must be at least 8 characters and contain uppercase, lowercase, and numbers');
    await expect(passwordError).toBeVisible();
  });

  test('should display multiple field-specific validation errors simultaneously', async ({ page }) => {
    // Submit form without filling any fields
    await page.getByRole('button', { name: 'Submit' }).click();

    // Verify all specific error messages appear
    const nameError = page.getByText('Name is required');
    const emailError = page.getByText('Email is required');
    const passwordError = page.getByText('Password is required');

    await expect(nameError).toBeVisible();
    await expect(emailError).toBeVisible();
    await expect(passwordError).toBeVisible();

    // Verify error count
    const errorMessages = page.getByRole('alert');
    await expect(errorMessages).toHaveCount(3);
  });

  test('should clear validation error when field is corrected', async ({ page }) => {
    // Submit form with invalid data
    await page.getByLabel('Email').fill('invalid-email');
    await page.getByRole('button', { name: 'Submit' }).click();

    // Verify error is displayed
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    // Correct the email field
    await page.getByLabel('Email').clear();
    await page.getByLabel('Email').fill('valid@example.com');

    // Verify error is removed
    await expect(emailError).not.toBeVisible();
  });

  test('should display specific validation error for mismatched password confirmation', async ({ page }) => {
    // Fill in form with mismatched passwords
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Email').fill('john@example.com');
    await page.getByLabel('Password').fill('SecurePass123!');
    await page.getByLabel('Confirm Password').fill('DifferentPass123!');

    // Submit the form
    await page.getByRole('button', { name: 'Submit' }).click();

    // Verify specific error message for password mismatch
    const mismatchError = page.getByText('Passwords do not match');
    await expect(mismatchError).toBeVisible();
  });

  test('should display specific validation error for invalid phone number format', async ({ page }) => {
    // Fill in form with invalid phone number
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Email').fill('john@example.com');
    await page.getByLabel('Password').fill('SecurePass123!');
    await page.getByLabel('Phone').fill('123');

    // Submit the form
    await page.getByRole('button', { name: 'Submit' }).click();

    // Verify specific error message for invalid phone format
    const phoneError = page.getByText('Phone number must be in format: (XXX) XXX-XXXX');
    await expect(phoneError).toBeVisible();
  });

  test('should display validation error with proper styling and accessibility', async ({ page }) => {
    // Submit form with invalid data
    await page.getByLabel('Email').fill('invalid');
    await page.getByRole('button', { name: 'Submit' }).click();

    // Verify error message is properly marked as alert
    const errorAlert = page.getByRole('alert').first();
    await expect(errorAlert).toBeVisible();

    // Verify error has proper ARIA attributes
    await expect(errorAlert).toHaveAttribute('role', 'alert');

    // Verify error message text is accessible
    const errorText = page.getByText('Please enter a valid email address');
    await expect(errorText).toBeVisible();
  });
});
